#!/usr/bin/env python3
"""Generated by android-build-broker v1. Regenerate with: broker.py init-repo REPOSITORY"""

from __future__ import annotations

import argparse
import json
import os
import stat
import subprocess
import sys
import time
import uuid
from pathlib import Path

if sys.version_info < (3, 10):
    raise SystemExit("request-android-build requires Python 3.10 or newer")

